U("          label = root.querySelector('.agents-head-label'),");U("          wide = root.querySelector('.agents-head-wide'),");U("          narrow = root.querySelector('.agents-head-narrow'),");U("          more = root.querySelector('.agents-more');");U("      if (!row || !label || !wide || !narrow || !more) {");U("        if (tries > 0) setTimeout(function(){ fitWhenThere(tries - 1); }, 250);");U("        return;");U("      }");U("      var gap = 3;");U("      var fit = function(){");U("        var folds = Array.prototype.slice.call(row.querySelectorAll('.agents-fold-hide'));");
