U("      } catch(_) {}");U("      fit();");U("    })(20);");U("    root.addEventListener('keydown', function(e){");U("      var t = e.target, tag = t && t.tagName;");U("      if (e.key === '/' && tag !== 'INPUT' && tag !== 'TEXTAREA') {");U("        var s = root.querySelector('.agents-search');");U("        if (s) { e.preventDefault(); s.focus(); }");U("  }");U("  return { arm: arm };");U("})();");U("agents-action ");U("Slot {slotOrder = ");U(", slotDepth = ");U(", slotTop = ");U("False, slotNode = ");
